import sys
from unittest.mock import MagicMock

class Mock(MagicMock):
    """Mock for unavailable packages that properly formats for type hints."""
    
    @classmethod
    def __getattr__(cls, name):
        return MagicMock()
    
    def __repr__(self):
        return f'{self._mock_name or "Mock"}'

MOCK_MODULES = ['PIL', 'colorthief', 'loguru', 'numpy', 'opensimplex', 'pyfastnoisesimd', 'tensorflow', 'tensorflow_addons', 'tensorflow_graphics', 'tensorflow_graphics.image', 'tensorflow_graphics.image.color_space', 'tensorflow_graphics.image.color_space.linear_rgb', 'tensorflow_graphics.image.color_space.srgb', 'skimage.transform', 'skimage.util']
sys.modules.update((mod_name, Mock()) for mod_name in MOCK_MODULES)


def setup(app):
    """Copy JavaScript bundle to _static for preset viewer."""
    # Copy dist/noisemaker.esm.js to _static/noisemaker.js
    dist_bundle = os.path.join(ROOT_DIR, 'dist', 'noisemaker.esm.js')
    static_dir = os.path.join(DOCS_DIR, '_static')
    static_bundle = os.path.join(static_dir, 'noisemaker.js')
    
    if not os.path.isfile(static_bundle):
        if os.path.isfile(dist_bundle):
            print(
                f"Warning: expected prebuilt bundle at {static_bundle}; "
                f"found {dist_bundle} but not copying per policy"
            )
        else:
            print(f"Warning: bundle missing at {static_bundle}")
    
